package se.karnerfors.roboreplacer.spike;

import java.util.List;
import lombok.Builder;
import lombok.ToString;
import lombok.Value;

/**
 * What one {@link java.awt.datatransfer.DataFlavor} on the clipboard turned out to hold.
 *
 * <p>Throw-away spike code. Immutable, built with a builder (both generated by Lombok).
 */
@Value
@Builder
class FlavourReport {

    /** What happened when we tried to read the flavour. */
    enum Outcome {
        READ,
        SKIPPED,
        FAILED
    }

    int index;

    /** Full MIME type including parameters, e.g. {@code text/html; class=java.io.InputStream; charset=UTF-8}. */
    String mimeType;

    String humanName;

    String representationClass;

    /** Native formats the JDK's flavor map associates with this flavour (candidates, not proof they are present). */
    List<String> nativeFormats;

    Outcome outcome;

    /** Class of the object {@code getTransferData} returned. */
    String resultClass;

    /** Characters, bytes, items or pixels, see {@link #sizeUnit}; -1 if unknown. A lower bound if truncated. */
    long size;

    String sizeUnit;

    /** True if we stopped reading at the spike's size cap. */
    boolean truncated;

    /** Observations about the content: line endings, no-break spaces, BOM, CF_HTML header and so on. */
    String traits;

    /** Why a flavour was skipped or failed. */
    String note;

    /**
     * Escaped excerpt of the content. Excluded from {@code toString()} on purpose: clipboard content must never
     * end up in a log by accident (NFR-002), and a Lombok-generated {@code toString()} would include it otherwise.
     */
    @ToString.Exclude
    String preview;
}
